         border: 1px solid var(--border);
         box-shadow: var(--shadow);
         transform: translateY(-180%);
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--accent);
         outline-offset: 2px;
       }

       .shell {
         width: min(1120px, calc(100% - 2rem));
         margin: 0 auto;
         padding: 5rem 0 3rem;
