         align-items: start;
         padding: 2rem;
         border: 1px solid var(--border);
         border-radius: calc(var(--radius) + 8px);
         background: var(--surface);
         backdrop-filter: blur(18px);
         box-shadow: var(--shadow);
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         width: fit-content;
         padding: 0.4rem 0.8rem;
