         list-style: none;
         cursor: pointer;
         padding: 1.2rem 1.35rem;
         font-size: 1.04rem;
         font-weight: 700;
       }

       .faq-item summary::-webkit-details-marker {
         display: none;
       }

       .faq-item summary:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -3px;
       }

