           background: Canvas;
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>

     <script>
       const faqData = [
         {
           question: "Why do cats purr?",
           answer: [
             "Cats often purr when they feel relaxed, but purring can also show uncertainty, request comfort, or help them self-soothe.",
             "Think of it as a multi-purpose signal rather than one fixed mood."
           ]
         },
         {
           question: "How much should I feed a cat?",
           answer: [
             "It depends on age, weight, activity level, and the calorie density of the food. The best starting point is the feeding guide on the package and a vet's advice for your cat's body condition.",
             "If your cat finishes meals instantly and seems hungry, adjust slowly rather than making a big jump."
           ]
         },
         {
           question: "Do indoor cats need enrichment?",
           answer: [
             "Yes. Indoor cats do best with daily play, places to climb, scratching surfaces, and predictable routines.",
             "A few minutes of interactive play can help reduce boredom and support healthy behavior."
           ]
         },
         {
           question: "How can I tell if a cat is happy?",
           answer: [
             "Relaxed posture, soft blinking, steady grooming, and choosing to stay near people are all good signs.",
             "A happy cat often looks unhurried and keeps its body loose."
           ]
         },
         {
           question: "Should I worry about hairballs?",
           answer: [
             "An occasional hairball can happen, especially in long-haired cats. Frequent vomiting, constipation, or a sudden change in appetite is worth a vet check.",
             "Regular brushing can reduce loose hair and make hairballs less common."
           ]
         }
       ];

       const statData = [
         ["5 quick answers", "A compact FAQ for cat curiosity"],
         ["0 clutter", "A simple layout that stays readable"],
         ["Keyboard friendly", "Native disclosure controls and visible focus"]
       ];

       function StatCard([value, label]) {
         return `
           <div class="stat">
             <strong>${value}</strong>
             <span>${label}</span>
           </div>
         `;
       }

       function FAQItem(item) {
         const paragraphs = item.answer.map((line) => `<p>${line}</p>`).join("");

         return `
           <div class="example">
             <details class="faq-item">
               <summary>${item.question}</summary>
               <div class="details">
                 ${paragraphs}
               </div>
             </details>
           </div>
         `;
       }

       function App() {
         return `
           <main id="maincontent" class="shell">
             <section class="hero" aria-labelledby="page-title">
               <div>
                 <div class="eyebrow">Cat FAQ</div>
                 <h1 id="page-title">Answers for the cat-obsessed, the cat-curious, and everyone in between.</h1>
                 <p class="lede">
                   A tidy FAQ page about cats with expandable answers, calm visuals, and a structure that
                   works well for keyboard and screen reader users.
                 </p>
               </div>
               <div class="stats" aria-label="Highlights">
                 ${statData.map(StatCard).join("")}
               </div>
             </section>

             <section class="faq" aria-labelledby="faq-title">
               <h2 id="faq-title" class="sr-only">
                 Frequently asked questions
               </h2>
               <div class="faq-grid">
                 ${faqData.map(FAQItem).join("")}
               </div>
               <p class="footer-note">Open any question to reveal the answer.</p>
             </section>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = App();
     </script>
   </body>
 </html>

